source("pre.R")
P <- function(label, expr) { cat("---", label, ": "); r <- tryCatch(expr, error = function(e) cat("ERROR<", class(e)[1], ">:", conditionMessage(e), "\n")); if (!is.null(r)) { if (is.character(r)) cat(r, sep = "\n") else try_(print(r)) }; invisible(r) }
kw <- jwk_generate("oct", alg = "A128KW", kid = "kek"); pw <- jwk_oct(charToRaw("password"))
P("enc vector, warnings not errors", { t <- jwe_encrypt("x", kw, enc = c("A128GCM", "A256GCM")); header_of(t) })
P("jws alg vector via key?", 1)
P("p2count partial on A128KW", header_of(jwe_encrypt("x", kw, header = list(p2count = 5))))
P("p2count partial on PBES2", header_of(jwe_encrypt("x", pw, "PBES2-HS256+A128KW", header = list(p2count = 1234))))
P("unprotected zip token decrypts?", { t <- jwe_encrypt("x", kw, format = "flattened", unprotected = list(zip = "DEF")); jwe_decrypt(t, kw, "A128KW", "A128CBC-HS256") })
cat("=== jwt + jwe\n")
now <- Sys.time()
inner <- jwt_encode(list(sub = "u"), key, "HS256", expires_in = 60)
P("nested: JWE(cty JWT) of JWS", { t <- jwe_encrypt(inner, kw, header = list(cty = "JWT")); cl <- jwt_decode(t, key, "HS256", decrypt = jwe_decryption(kw, "A128KW", "A128CBC-HS256")); print(attr(cl, "header")); cl$sub })
P("JWE without decrypt", jwt_decode(jwe_encrypt(inner, kw, header = list(cty = "JWT")), key, "HS256"))
P("JWE encrypted-only symmetric", { t <- jwe_encrypt('{"sub":"u","exp":9999999999}', kw, header = list(typ = "JWT")); cl <- jwt_decode(t, key, "HS256", decrypt = jwe_decryption(kw, "A128KW", "A128CBC-HS256")); print(attr(cl, "header")); cl$sub })
P("JWE encrypted-only symmetric no typ", { t <- jwe_encrypt('{"sub":"u","exp":9999999999}', kw); jwt_decode(t, key, "HS256", decrypt = jwe_decryption(kw, "A128KW", "A128CBC-HS256"))$sub })
rsa <- jwk_generate("RSA")
P("JWE encrypted-only RSA", { t <- jwe_encrypt('{"sub":"u","exp":9999999999}', rsa, "RSA-OAEP"); jwt_decode(t, key, "HS256", decrypt = jwe_decryption(rsa, "RSA-OAEP", "A128CBC-HS256")) })
P("JWE RSA nested", { t <- jwe_encrypt(inner, rsa, "RSA-OAEP", header = list(cty = "JWT")); jwt_decode(t, key, "HS256", decrypt = jwe_decryption(rsa, "RSA-OAEP", "A128CBC-HS256"))$sub })
P("JWE nested cty application/jwt", { t <- jwe_encrypt(inner, rsa, "RSA-OAEP", header = list(cty = "application/jwt")); jwt_decode(t, key, "HS256", decrypt = jwe_decryption(rsa, "RSA-OAEP", "A128CBC-HS256"))$sub })
P("JWE cty JWT but plaintext claims", { t <- jwe_encrypt('{"sub":"u","exp":9999999999}', kw, header = list(cty = "JWT")); jwt_decode(t, key, "HS256", decrypt = jwe_decryption(kw, "A128KW", "A128CBC-HS256")) })
P("JWS nested in JWS", { t <- jws_sign(inner, key, "HS256", header = list(cty = "JWT", typ = "JWT")); jwt_decode(t, key, "HS256")$sub })
P("JWS nested twice", { t <- jws_sign(jws_sign(inner, key, "HS256", header = list(cty = "JWT")), key, "HS256", header = list(cty = "JWT")); jwt_decode(t, key, "HS256")$sub })
P("JWE containing JWE", { t <- jwe_encrypt(jwe_encrypt(inner, kw, header = list(cty = "JWT")), kw, header = list(cty = "JWT")); jwt_decode(t, key, "HS256", decrypt = jwe_decryption(kw, "A128KW", "A128CBC-HS256")) })
P("decrypt arg list not class", jwt_decode(inner, key, "HS256", decrypt = list(key = kw, algorithms = "A128KW", encryptions = "A128CBC-HS256")))
P("JSON JWS token as JWT", jwt_decode(jws_sign('{"exp":9999999999}', key, "HS256", format = "flattened"), key, "HS256"))
P("typ check on inner or outer? outer typ=JWT, inner typ=other", { i2 <- jwt_encode(list(sub = "u"), key, "HS256", expires_in = 60, header = list(typ = "other")); t <- jwe_encrypt(i2, kw, header = list(cty = "JWT", typ = "JWT")); jwt_decode(t, key, "HS256", decrypt = jwe_decryption(kw, "A128KW", "A128CBC-HS256"))$sub })
cat("=== decoder closure\n")
aud <- "api"; alg <- "HS256"; lim <- jose_limits(); kk <- key
chk <- jwt_decoder(kk, alg, audience = aud, limits = lim, claims = list(sub = "u"))
tok <- jwt_encode(list(sub = "u", aud = "api"), key, "HS256", expires_in = 60)
aud <- "other"; alg <- "HS512"; kk <- jwk_oct(as.raw(2:33)); lim <- jose_limits(token = 1)
P("decoder after rebinding", chk(tok)$sub)
P("decoder == decode", identical(chk(tok, now = now), jwt_decode(tok, key, "HS256", audience = "api", claims = list(sub = "u"), now = now)))
P("decoder now arg numeric", chk(tok, now = 5))
P("decoder expired later", chk(tok, now = Sys.time() + 3600))
P("decoder formals", names(formals(chk)))
P("decoder resolver key lazy", { n <- 0; chk2 <- jwt_decoder(function(h) { n <<- n + 1; key }, "HS256", audience = "api"); chk2(tok); chk2(tok); n })
P("decoder missing algorithms", jwt_decoder(key))
P("decoder bad required", jwt_decoder(key, "HS256", required = 5))
P("decoder bad limits", jwt_decoder(key, "HS256", limits = list(token = 5)))
P("decoder bad key not checked early?", { f <- jwt_decoder("notakey", "HS256"); f(tok) })
P("decode bad limits", jwt_decode(tok, key, "HS256", audience = "api", limits = list(token = 5)))
P("decode limits token small", jwt_decode(tok, key, "HS256", audience = "api", limits = jose_limits(token = 10)))
cat("=== signer captured values\n")
h <- list(typ = "A"); s <- jws_signer(key, "HS256", header = h); h$typ <- "B"; P("signer header", header_of(jws_sign("x", list(s))))
r <- jwe_recipient(kw, "A128KW"); P("recipient", class(r))
d <- jwe_decryption(kw, "A128KW", "A128CBC-HS256"); kw2 <- kw; P("decryption holds key", identical(d$key, kw))
cat("=== limits\n")
for (v in list(0, 1, 1.5, -1, NA, NA_integer_, Inf, -Inf, "5", 2^31, 2^53 + 2, c(1, 2), NULL, TRUE, 5L)) P(paste("limits token", deparse(v)), unclass(jose_limits(token = v))$token)
P("limits payload boundary", { t <- jws_sign(strrep("a", 10), key, "HS256"); c(ok10 = inherits(tryCatch(jws_verify(t, key, "HS256", limits = jose_limits(payload = 10)), error = function(e) e), "jws_verified"), ok9 = inherits(tryCatch(jws_verify(t, key, "HS256", limits = jose_limits(payload = 9)), error = function(e) e), "jws_verified")) })
P("limits payload boundary 11 bytes vs limit 10/11/12", { t <- jws_sign(strrep("a", 11), key, "HS256"); sapply(c(9, 10, 11, 12), function(n) inherits(tryCatch(jws_verify(t, key, "HS256", limits = jose_limits(payload = n)), error = function(e) e), "jws_verified")) })
P("limits header boundary", { t <- jws_sign("x", key, "HS256"); n <- nchar(header_of(t)); cat("hdr bytes", n, "\n"); sapply(n + (-3:1), function(m) inherits(tryCatch(jws_verify(t, key, "HS256", limits = jose_limits(header = m)), error = function(e) e), "jws_verified")) })
P("limits token boundary", { t <- jws_sign("x", key, "HS256"); n <- nchar(t); sapply(n + (-1:1), function(m) inherits(tryCatch(jws_verify(t, key, "HS256", limits = jose_limits(token = m)), error = function(e) e), "jws_verified")) })
P("limits detached payload", { t <- jws_sign(strrep("a", 11), key, "HS256", detached = TRUE); sapply(c(10, 11), function(n) inherits(tryCatch(jws_verify(t, key, "HS256", payload = strrep("a", 11), limits = jose_limits(payload = n)), error = function(e) e), "jws_verified")) })
P("limits ciphertext boundary GCM 11 bytes", { k <- jwk_oct(as.raw(1:16)); t <- jwe_encrypt(strrep("a", 11), k, "dir", "A128GCM"); sapply(c(9, 10, 11, 12), function(n) inherits(tryCatch(jwe_decrypt(t, k, "dir", "A128GCM", limits = jose_limits(payload = n)), error = function(e) e), "jwe_decrypted")) })
P("limits keys", { s <- do.call(jwk_set, lapply(1:5, function(i) jwk_oct(as.raw(i + 1:32)))); t <- jws_sign("x", s[[5]], "HS256"); c(tryCatch(class(jws_verify(t, s, "HS256", limits = jose_limits(keys = 4)))[1], error = function(e) conditionMessage(e)), class(jws_verify(t, s, "HS256", limits = jose_limits(keys = 5)))[1]) })
P("limits signatures", { g <- jws_sign("x", list(jws_signer(key, "HS256"), jws_signer(key, "HS256")), format = "general"); c(tryCatch(class(jws_verify(g, key, "HS256", limits = jose_limits(signatures = 1)))[1], error = function(e) conditionMessage(e))) })
P("peek limits arg", jose_peek(tok, limits = jose_limits(token = 10)))
P("peek detached/b64false", { p <- jose_peek(jws_sign('{"a":1}', key, "HS256", b64 = FALSE, detached = TRUE)); str(p[c("payload", "claims", "signing_input")]) })
P("peek non-json payload", { p <- jose_peek(jws_sign("hello", key, "HS256")); print(p); rawToChar(p$signing_input[[1]]) })
P("peek general 2 sig", jose_peek(jws_sign("x", list(jws_signer(key, "HS256"), jws_signer(key, "HS256", unprotected = list(u = 1))), format = "general")))
P("peek claims long value", jose_peek(jwt_encode(list(s = strrep("é", 100), n = NULL), key, "HS256")))
P("zujose_info", { i <- zujose_info(); str(i); all(i$available) })
